# ---------------- 主程序 ----------------
def first_line(cid):
    d = json.load(open(os.path.join(IN_DIR, cid + ".json"), encoding="utf-8"))
    ctx = d.get("context", {})
    att = ctx.get("attachments", {}) or {}
    q = ctx.get("question", "")
    at = ctx.get("asked_at", "")
    hx = att.get("hexagram", "")
    if "tradition" in d:
        head = f"tradition={d['tradition']}（卡面逐字）"
    elif "system" in d:
        head = f"system={d['system']}（卡面逐字）"
    else:
        head = "卡面未标注 tradition/system 字段，按题面体裁自决：六爻纳甲（卡面载铜钱摇卦与逐爻装卦表，体裁即六爻）"
    return f"{head}；本例卡面：问「{q}」，占时「{at}」，卦「{hx}」。"

def main():
    batches = json.load(open(os.path.join(BASE, "runs/round71/batches.json"), encoding="utf-8"))
    ids = batches["B07"] + batches["B08"] + batches["B09"]
    assert len(ids) == 60, len(ids)
    assert set(ids) == set(DATA.keys()), (set(ids) ^ set(DATA.keys()))
    os.makedirs(OUT_DIR, exist_ok=True)
    counts = {"changed_main": 0, "reserve_used": 0, "disputed": 0}
    written = 0
    for cid in ids:
        pred, basis_body, conf, trig = DATA[cid]
        basis = first_line(cid) + basis_body
        rec = {"case_id": cid, "prediction_text": pred, "basis": basis,
               "confidence": conf, "trigger": trig}
        with open(os.path.join(OUT_DIR, cid + ".json"), "w", encoding="utf-8") as f:
            json.dump(rec, f, ensure_ascii=False, indent=1)
        written += 1
        for k in counts:
            if trig[k]:
                counts[k] += 1
    # 逐件核对：按本批 id 清单逐件打开
    ok = 0
    for cid in ids:
        p = os.path.join(OUT_DIR, cid + ".json")
        r = json.load(open(p, encoding="utf-8"))
        assert r["case_id"] == cid and set(r.keys()) == {"case_id", "prediction_text", "basis", "confidence", "trigger"}
        assert 0 <= r["confidence"] <= 1
        ok += 1
    assert ok == 60
    print(f"batch_cases=60 written={written} verified={ok} trigger_counts={counts}")

if __name__ == "__main__":
    main()
